/*
 * CryNet — verification probes for Stage 2a.
 *
 * The host parity test proves that the C front end matches the Python
 * training pipeline on a desktop. These probes carry that check onto the
 * ESP32-S3: the device generates the same PCM from the same closed-form
 * definitions, runs its own front end, and compares the quantised
 * features against the ones the *Python* pipeline produced on the host.
 *
 * The expected features live in crynet_probe_refs.h, which is generated by
 * firmware/tools/gen_probe_refs.py from the notebook's own front end.
 *
 * Probe definitions (must stay in step with gen_probe_refs.py):
 *
 *   0  silence      every sample is 0
 *   1  dc_bias      every sample is 18000 — the INMP441's quiescent bias,
 *                   which the front end must remove completely
 *   2  tone         0.35*sin(2*pi*420*t) + 0.12*sin(2*pi*1350*t)
 *   3  noise        0.05 * uniform(-1, 1) from a 32-bit LCG
 *
 * t = n / 16000. PCM conversion is int16 = (int16)(clip(x, -1, 1) * 32767),
 * truncating toward zero.
 */

#ifndef CRYNET_PROBES_H
#define CRYNET_PROBES_H

#include <stdint.h>

#define CRYNET_PROBE_COUNT        4
#define CRYNET_PROBE_SAMPLES      32000
#define CRYNET_PROBE_FEATURE_BYTES (81 * 64)

/* Name of a probe, for the log. */
const char *crynet_probe_name(int index);

/* Fill `pcm` with CRYNET_PROBE_SAMPLES int16 samples for the given probe. */
void crynet_probe_pcm(int index, int16_t *pcm);

/* CRC32 (zlib convention) over the probe's PCM — lets the host confirm
 * that both sides generated bit-identical input. */
uint32_t crynet_probe_pcm_crc(int index);

/* Expected quantised features, from the Python pipeline. */
const int8_t *crynet_probe_expected(int index);

/* CRC32 over each probe's expected features (from the host). */
uint32_t crynet_probe_expected_crc(int index);

/* CRC32 over each probe's expected PCM (from the host) — the device
 * compares its own generated PCM against this to prove both sides built
 * bit-identical input. */
uint32_t crynet_probe_expected_pcm_crc(int index);

#endif /* CRYNET_PROBES_H */
